package org.icu.sepsis.deterioration;import static org.junit.jupiter.api.Assertions.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import org.icu.sepsis.domain.Domain.*;
class DeteriorationTest{Instant now=Instant.parse("2026-11-19T08:00:00Z");Observation cr(double value,int hours){var o=new Observation();o.parameterCode="CREA";o.value=value;o.unit="μmol/L";o.eventTime=now.minusSeconds(hours*3600);o.qualityStatus="valid";return o;}
@Test void risingCreatinineTriggersCandidateWithoutPretendingBaselineOrUrineConfirmed(){var r=DeteriorationService.aki(List.of(cr(80,36),cr(110,1)),now,true);assertEquals("candidate",r.get("status"));assertEquals("unknown",r.get("urineStatus"));assertTrue(r.get("comparisonBasis").toString().contains("非已确认"));}
@Test void stableValuesDoNotExcludeAki(){var r=DeteriorationService.aki(List.of(cr(100,36),cr(105,1)),now,true);assertEquals("not_triggered",r.get("status"));assertTrue(r.get("detail").toString().contains("不能排除"));}
@Test void onePointAndFailedSourceRemainUnknown(){assertEquals("unknown",DeteriorationService.aki(List.of(cr(400,1)),now,true).get("status"));assertEquals("unknown",DeteriorationService.aki(List.of(cr(80,30),cr(400,1)),now,false).get("status"));}
@Test void futureAndUnconfirmedCannotCreateCandidate(){var p=cr(300,-1);var report=cr(400,1);report.clinicalUse="context_only";assertEquals("unknown",DeteriorationService.aki(List.of(cr(80,30),p,report),now,true).get("status"));}
@Test void conflictsAndWrongUnitsRemainUnknown(){assertEquals("unknown",DeteriorationService.aki(List.of(cr(80,30),cr(110,1),cr(140,1)),now,true).get("status"));var o=cr(2,1);o.unit="mg/dL";assertEquals("unknown",DeteriorationService.aki(List.of(o),now,true).get("status"));}
@Test void sixSystemsDoNotInventGreenOrCrossStayKidney(){var p=new Patient();p.id="synthetic";p.encounterId="stay";p.department="test";var a=cr(80,30);a.encounterId="other";var b=cr(200,1);var r=DeteriorationService.evaluate(p,now,Map.of("available",true),List.of(a,b),true);assertEquals(6,((List<?>)r.get("organs")).size());assertEquals("unknown",((Map<?,?>)r.get("aki")).get("status"));assertEquals(0L,r.get("affectedSystems"));assertNull(r.get("complete"));}
@Test void earlierCandidateIsRetainedWhenLastValueFallsBelowTrigger(){var r=DeteriorationService.aki(List.of(cr(80,160),cr(150,130),cr(100,100),cr(100,1)),now,true);assertEquals("not_triggered",r.get("status"));assertEquals(true,r.get("historicalCandidate"));assertEquals("prior_candidate",r.get("courseStatus"));assertFalse(((List<?>)r.get("candidateEvents")).isEmpty());assertTrue(r.get("detail").toString().contains("确认恢复"));}
@Test void sameTimeDuplicatesDoNotProduceFakeAdditionalPoints(){var r=DeteriorationService.aki(List.of(cr(80,30),cr(110,1),cr(110,1)),now,true);assertEquals(2,((List<?>)r.get("series")).size());assertEquals(1,((List<?>)r.get("candidateEvents")).size());}

@Test void onlyMatchingPatientStayAndDepartmentContributeVerifiedRenalEvidence(){var p=new Patient();p.id="p";p.encounterId="stay";p.department="ICU";var a=cr(80,30);var b=cr(120,1);for(var o:List.of(a,b)){o.patientId=p.id;o.encounterId=p.encounterId;o.department=p.department;}var r=DeteriorationService.evaluate(p,now,Map.of("available",true),List.of(a,b),true);assertEquals("candidate",((Map<?,?>)r.get("aki")).get("status"));var renal=(Map<?,?>)((List<?>)r.get("organs")).get(2);assertEquals(1,((List<?>)renal.get("evidence")).size());a.department="other";assertEquals("unknown",((Map<?,?>)DeteriorationService.evaluate(p,now,Map.of("available",true),List.of(a,b),true).get("aki")).get("status"));}
}
